{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C58"],
      "claim": "Darifenacin, the closest structural analogue by Morgan similarity, has a human oral bioavailability of only 15-19%, below the 20% threshold, and shares a piperidine and fused ether-aromatic system with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Avanafil, a heteroaromatic basic-amine drug with a fused ring system, has a human oral bioavailability of 8-10%, supporting low F for similarly polar, ionizable heteroaromatic molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Lurtotecan, a fused heteroaromatic lactam with a basic amine, has oral bioavailability as low as 11%, consistent with poor absorption for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Prucalopride, which contains a piperidine and benzofuran ether, has absolute oral bioavailability greater than 90%, providing contradictory high-F evidence, but its smaller size and lower polarity limit transferability to the larger, more polar query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C38"],
      "claim": "Tasimelteon has an absolute oral bioavailability of 38%, above the 20% threshold, but its much smaller, less polar structure makes this high-F evidence less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability (<20%) based primarily on the closest analogue darifenacin (F 15-19%) and other low-F heteroaromatic/basic-amine drugs, reinforced by the unfavorable absorption prior (low logD, high TPSA, extensive ionization). High-F analogues are numerous but structurally less transferable due to smaller size and lower polarity.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities to all evidence molecules are low (0.18-0.23), limiting structural transferability.",
    "No direct permeability, efflux, or first-pass metabolism data for the query.",
    "Formulation and dose effects can shift F across the 20% threshold, as seen with darifenacin."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

